import type { Level } from './words';

/** Identifies a word's pre-generated neural audio in Supabase Storage. A `Word` satisfies this. */
export type AudioRef = { level: Level; id: number };

const BASE = (process.env.EXPO_PUBLIC_SUPABASE_URL ?? '').replace(/\/+$/, '');

/** Public URL of audio/<level>/<id>_<en|bg>.mp3 (generated by `tools/vocab/vocab.py audio`). */
export function neuralAudioUrl(ref: AudioRef, language: string): string {
  return `${BASE}/storage/v1/object/public/audio/${ref.level}/${ref.id}_${language
    .slice(0, 2)
    .toLowerCase()}.mp3`;
}
